package com.hmdp.ai.runtime.agent;
import com.hmdp.ai.application.dto.agent.AgentInputRequest;import com.hmdp.ai.domain.agent.PublishedAgentDefinition;import com.hmdp.ai.domain.run.*;import com.hmdp.ai.domain.workflow.*;import com.hmdp.ai.runtime.workflow.WorkflowRuntime;import org.springframework.stereotype.Component;
@Component public class WorkflowAgentExecutionEngine implements AgentExecutionEngine {private final WorkflowRepository workflows;private final WorkflowRuntime runtime;private final WorkflowValidator validator;public WorkflowAgentExecutionEngine(WorkflowRepository w,WorkflowRuntime r,WorkflowValidator v){workflows=w;runtime=r;validator=v;}public AgentRunOutput execute(PublishedAgentDefinition d,ExecutionContext c,AgentInputRequest input){WorkflowDefinition w=workflows.findVersion(c.getTenantId(),c.getWorkspaceId(),d.getVersion().getWorkflowVersionId()).orElseThrow(()->new IllegalStateException("workflow version not found"));if(!validator.validate(w).isValid())throw new IllegalStateException("published workflow is invalid");return runtime.execute(w,d,c,input);}}
